class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res, path = [], []

        def dfs(start):
            if start == len(s):
                res.append(path[:])
                return
            for end in range(start + 1, len(s) + 1):
                piece = s[start:end]
                if piece == piece[::-1]:        # 这一段是回文才切
                    path.append(piece)
                    dfs(end)
                    path.pop()

        dfs(0)
        return res

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        if not s:
            return [[]]
        return [[s[:i]] + rest
                for i in range(1, len(s) + 1) if s[:i] == s[i - 1::-1]
                for rest in self.partition(s[i:])]

